pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val1, uint256 val2) internal {
        bool r1;
        try c.SetMinSum(val1) { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.SetMinSum(val2) { r2 = false; } catch { r2 = true; }
        assertTrue(!r1 && !r2 && c.MinSum() == val2);
    }

    function testFuzz_run(uint256 val1, uint256 val2) public {
        _run(val1, val2);
    }

    receive() external payable {}
}
